import torch
import numpy as np

# Let me create test images with patches in different corners to identify the trigger
def create_patch_image(patch_type='white', corner='tl', patch_size=4):
    """Create a clean image with a patch in the specified corner"""
    # Start with a random clean image
    img = x_clean[0].clone().float() / 255.0
    img = img.permute(1, 2, 0).numpy()  # HWC

    h, w = 32, 32
    if corner == 'tl':
        r_start, c_start = 1, 1
    elif corner == 'tr':
        r_start, c_start = 1, w - patch_size - 1
    elif corner == 'bl':
        r_start, c_start = h - patch_size - 1, 1
    elif corner == 'br':
        r_start, c_start = h - patch_size - 1, w - patch_size - 1

    if patch_type == 'white':
        patch = np.ones((patch_size, patch_size, 3))
    elif patch_type == 'checkerboard':
        patch = np.zeros((patch_size, patch_size, 3))
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[i, j] = 1.0
    elif patch_type == 'random':
        patch = np.random.randint(0, 2, (patch_size, patch_size, 3)).astype(float)

    img[r_start:r_start+patch_size, c_start:c_start+patch_size] = patch

    # Convert back to tensor format
    img_tensor = torch.from_numpy(img).permute(2, 0, 1).unsqueeze(0) * 255
    return img_tensor.to(torch.uint8)

